// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint64 number, uint64 timestamp) public {
        vm.prank(DEPOSITOR);
        c.setL1BlockValues(number, timestamp, 0, bytes32(0), 0, bytes32(0), 0, 0);
        assertTrue(c.timestamp() == timestamp);
    }
}
